import { Component, OnInit, inject, signal, DestroyRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ActivatedRoute, RouterModule } from '@angular/router';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { TrackingService, TrackingStatus } from '../../shared/services/tracking.service';

@Component({
  selector: 'app-tracking',
  standalone: true,
  imports: [CommonModule, RouterModule],
  templateUrl: './tracking.component.html',
  styles: [`
    .fs-7 { font-size: 0.8rem; }
  `]
})
export class TrackingComponent implements OnInit {
  private readonly route = inject(ActivatedRoute);
  private readonly trackingService = inject(TrackingService);
  private readonly destroyRef = inject(DestroyRef);

  readonly loading = signal<boolean>(true);
  readonly error = signal<boolean>(false);
  readonly data = signal<TrackingStatus | null>(null);

  ngOnInit(): void {
    const folio = this.route.snapshot.paramMap.get('folio');
    if (!folio) {
      this.loading.set(false);
      this.error.set(true);
      return;
    }

    this.trackingService.getStatus(folio)
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: (res) => {
          this.data.set(res);
          this.loading.set(false);
        },
        error: (err) => {
          this.data.set(err.error || null);
          this.error.set(true);
          this.loading.set(false);
        }
      });
  }
}
